parts.text:
{
  "conversations": [
    {
      "title": "Ask for a specific place",
      "lines": [
        { "speaker": "you", "text": "Where's the train station, please?" },
        { "speaker": "partner", "text": "It's far from here." },
        { "speaker": "partner", "text": "It's just around the corner.", "or": true },
        { "speaker": "you", "text": "Can I take the tram?" },
        { "speaker": "partner", "text": "Yes, line nine goes there." },
        { "speaker": "partner", "text": "No, you need the metro.", "or": true }
      ]
    },
    {
      "title": "Understand basic directions",
      "lines": [
        { "speaker": "partner", "text": "Go straight ahead." },
        { "speaker": "partner", "text": "Turn left at the traffic light." },
        { "speaker": "partner", "text": "Turn right at the corner.", "or": true },
        { "speaker": "you", "text": "Is it on the right side?" },
        { "speaker": "partner", "text": "Yes, you can't miss it." },
        { "speaker": "partner", "text": "No, it's on the left.", "or": true }
      ]
    },
    {
      "title": "Ask to repeat or slow down",
      "lines": [
        { "speaker": "partner", "text": "Take the second stop and transfer." },
        { "speaker": "you", "text": "Could you speak slower, please?" },
        { "speaker": "partner", "text": "Sure. Take the second stop." },
        { "speaker": "you", "text": "Could you repeat that, please?" },
        { "speaker": "partner", "text": "Transfer to bus five." },
        { "speaker": "you", "text": "Thanks a lot." }
      ]
    }
  ],
  "vocab": [
    "station",
    "tram",
    "metro",
    "stop",
    "transfer",
    "straight",
    "left",
    "right",
    "corner",
    "slow",
    "repeat",
    "far",
    "near"
  ]
}
